INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1613, 'Crazy House Đà Lạt (Biệt Thự Hằng Nga)', 'crazy-house', '<p><strong>Crazy House</strong> trước đây là một khu biết thự có tên gọi là <strong>Biệt thự&nbsp;Hằng Nga</strong>. Nhưng sau này chủ ở đây, một vị kiến trúc sư, đã thay đổi tên và xây dựng nên phong cách đặc biệt của nó. Khu biệt thự rộng gần <strong>2.000 mét vuông</strong> với những kiến trúc kỳ lạ đã luôn nằm trong top những ngôi nhà có <strong>kiến trúc độc đáo</strong> của nhiều bình chọn trên thế giới. Những kiến trúc ở đây luôn theo xu hướng độc lập riêng, một chút quái dị và hướng đến những tự do sáng tạo của con người. Bạn nên dành thời gian để tham quan điểm hay lưu trú ở điểm du lịch thú vị này!</p>
<p><figure id="attachment_1617" aria-describedby="caption-attachment-1617" style="width: 600px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1617" src="https://media.huynhhieutravel.com/Crazy-House4.jpg" alt="Crazy House" width="600" height="449"><figcaption id="caption-attachment-1617" class="wp-caption-text">Crazy House</figcaption></figure></p>
<h2>Thông tin Crazy House (Biệt Thự Hằng Nga) Đà Lạt</h2>
<p>Nằm trong trung tâm Đà Lạt và khoảng cách chưa đến <strong>2km</strong> từ chợ Đà Lạt. Nơi đây là một điểm tham quan thú vị của khách du lịch. Đặc biệt, nơi đây thu hút khá nhiều khách du lịch nước ngoài vì những đánh giá cao ở những trang báo hay đặc biệt là trang <strong>tripadvisor</strong>. Nơi đây bao gồm nhiều tòa nhà với những kiến trụ kỳ dị, đặc biệt và rất sáng tạo. Bạn sẽ được trải qua những không gian mới lạ và phiêu lưu khi leo những cây cầu thang chơi vơi trên cao.</p>
<p><strong>Địa chỉ</strong>: 3 Huỳnh Thúc Kháng, Phường 4, thành phố Đà Lạt, tỉnh Lâm Đồng.</p>
<p><strong>Số điện thoại</strong>: 0633822070</p>
<p><strong>Email</strong>:&nbsp;info@crazyhouse.vn</p>
<p><strong>Giờ mở cửa</strong>: 8h30-19h00</p>
<p><iframe style="border: 0;" src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3903.5730150145737!2d108.42845061481144!3d11.934775191541956!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x317113331aee38a5%3A0x3f766cbad7773c86!2zQmnhu4d0IHRo4buxIEjhurFuZyBOZ2E!5e0!3m2!1svi!2s!4v1535097487293" width="600" height="450" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<h3>Lịch sử&nbsp;Crazy House</h3>
<p>Khu biệt thự được khai trương vào năm <strong>1990</strong> và tiếp tục nâng cấp các hạng mục chính đến năm <strong>2010</strong> thì hoàn chỉnh. Bạn đầu nó được xây với phong cách: Trong lòng những <strong>gốc cây và các phiến đá</strong> bị cưa cụt, con người vẫn có thể tạo nên những gian phòng ấm cúng, tiện nghi và thậm chí là cả những tòa lâu đài đầy vẻ huyền bí và hấp dẫn. Nơi đây cũng là một khách sạn dành cho khách lưu trú ngắn hoặc dài ngày.</p>
<p>Chủ nhân của ngôi nhà là bà <strong>Đặng Việt Nga</strong>, một kiến trúc sư đầy đam mê và yêu mến Đà Lạt. Bà còn một thân phận khác khá đặc biệt là con gái của cố Tổng bí thư Trường Chinh. Bà từng du học ở Trung Quốc, Liên Xô và có bằng tiến sĩ về kiến trúc. Với đam mê đặc biệt của mình, bà đã sáng tạo nên một Crazy House đầy độc đáo.</p>
<p>Crazy House từng nằm trong top những ngôi nhà đặc biệt nhất của nhiều tờ báo nước ngoài và được đánh giá rất cao trên <strong>tripadvisor</strong>.</p>
<p><figure id="attachment_1616" aria-describedby="caption-attachment-1616" style="width: 600px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1616" src="https://media.huynhhieutravel.com/Crazy-House3.jpg" alt="Những ngôi nhà hình thù kỳ quái của Crazy House" width="600" height="400"><figcaption id="caption-attachment-1616" class="wp-caption-text">Những ngôi nhà hình thù kỳ quái của Crazy House</figcaption></figure></p>
<h2><span id="Thung_Lung_Vang_co_gi_choi">Kiến trúc Crazy House</span></h2>
<p>Ý tưởng ban đầu của khu nhà và chủ đạo đến bây giờ là những ngôi nhà được xây trong những gốc cây cổ thụ và phiến đá cụt.</p>
<p><strong>Biệt thự Hằng Nga</strong> bao gồm nhiều tòa nhà và nhà khách, quán cà phê và phòng trưng bày nghệ thuật với phong cách đặc biệt. Các nội thất của tòa nhà bao gồm hang động, hành lang quanh co, đồ nội thất kỳ quặc và những bức tượng động vật với kích cỡ lớn. Không có những đường thẳng hay góc thẳng, không &#8220;ngang hàng thẳng lối&#8221;. Có thể tạo ấn tượng là không gian, hành lang, cầu thang, cửa sổ hoặc đồ nội thất &#8211; tất cả mọi thứ có vẻ như thể đã bị nấu tan chảy ở nhiệt độ cao và sau đó đóng băng trong hình dạng kỳ cục.</p>
<p><figure id="attachment_1614" aria-describedby="caption-attachment-1614" style="width: 481px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="wp-image-1614 size-full" src="https://media.huynhhieutravel.com/Crazy-House.jpg" alt="Khách du lịch tham quan Crazy House" width="481" height="599"><figcaption id="caption-attachment-1614" class="wp-caption-text">Khách du lịch tham quan Crazy House</figcaption></figure></p>
<p>Giữa các tòa nhà là những mấu cây, rể cây xương xẩu làm bằng bê tông và mạng nhện khổng lồ làm bằng dây kẽm. Có một phòng trà nhỏ bên trong một tượng Hươu cao cổ to. Các phòng nghỉ có tên phòng khá độc đáo như: Quả bầu, Kangaroo, Con gấu, Con ong,&#8230;<sup id="cite_ref-4" class="reference"></sup></p>
<p>Các phòng đều có thể được đặt chỗ thuê để nghỉ qua đêm. Hiện tại, mỗi năm &#8220;Crazy House&#8221; đón khoảng vài trăm nghìn lượt khách tới tham quan, trong đó có rất nhiều khách nước ngoài.</p>
<p>Ngoài ra, ở đây còn có một gian phòng là khu tưởng niệm cố Tổng bí thư Trường Chinh. Bạn sẽ được tham quan một số vật dụng cổ và những tài liệu về ông ở đây.</p>
<h2>Đường đi đến Crazy House</h2>
<p>Đường đi đến Crazy House khá dễ dàng. Nó nằm cách chợ Đà Lạt chỉ gần 2km. Bạn có thể đi bằng xe máy và gửi xe ở nhà kế bên hoặc đậu xe hơi ở gần đó và đi bộ vào.</p>
<p>Bạn có thể điền tọa độ của bạn vào link này để tìm đường đi: <a href="https://www.google.com/maps/dir/9.679723,105.5683486/Bi%E1%BB%87t+th%E1%BB%B1+H%E1%BA%B1ng+Nga,+03+Huynh+Thuc+Khang+Street,Ward+4,Dalat+City+67000,Lam+Dong,+Tr%E1%BA%A7n+Ph%C3%BA,+Ph%C6%B0%E1%BB%9Dng+4,+Tp.+%C4%90%C3%A0+L%E1%BA%A1t,+L%C3%A2m+%C4%90%E1%BB%93ng,+Ph%C6%B0%E1%BB%9Dng+4,+Vietnam,+L%C3%A2m+%C4%90%E1%BB%93ng/@10.7999064,104.7750993,7z/data=!3m1!4b1!4m18!1m8!3m7!1s0x317113331aee38a5:0x3f766cbad7773c86!2zQmnhu4d0IHRo4buxIEjhurFuZyBOZ2E!5m1!1s2018-09-21!8m2!3d11.9347751!4d108.430639!4m8!1m1!4e1!1m5!1m1!1s0x317113331aee38a5:0x3f766cbad7773c86!2m2!1d108.4306393!2d11.9347752">Tọa độ và đường đi đến Crazy House</a></p>
<p><figure id="attachment_1618" aria-describedby="caption-attachment-1618" style="width: 479px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1618" src="https://media.huynhhieutravel.com/Crazy-House5.jpg" alt="Crazy House Đà Lạt" width="479" height="599"><figcaption id="caption-attachment-1618" class="wp-caption-text">Crazy House Đà Lạt</figcaption></figure></p>
<h2>Kinh nghiệm đi Crazy House</h2>
<ul>
<li>Bạn nên chuẩn bị nước và bánh ngọt sẳn khi đến đây. Hoặc ăn sáng trước khi đi. Đến đây bạn phải tham quan những tòa nhà với cầu thang leo cao. Nó sẽ mất thể lực của bạn.</li>
<li>Nơi đây có những đoạn cầu thang chênh vênh và khá cao. Nếu có tiền sử bệnh tim hoặc mang theo con nhỏ bạn hãy lưu ý việc này.</li>
</ul>
<p><figure id="attachment_1622" aria-describedby="caption-attachment-1622" style="width: 960px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1622" src="https://media.huynhhieutravel.com/Crazy-House10.jpg" alt="Một con đường đi xuống ở đây" width="960" height="720" srcset="https://media.huynhhieutravel.com/Crazy-House10.jpg 960w, https://media.huynhhieutravel.com/Crazy-House10-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1622" class="wp-caption-text">Một con đường đi xuống ở đây</figcaption></figure></p>
<h3>Thời điểm thích hợp đi Crazy House</h3>
<p>Crazy House gần như mở quanh năm, nhưng bạn cũng nên lựa chọn thời điểm thích hợp để đi. Bạn nên tránh dịp lễ tết ra vì sẽ khá đông du khách đến đây và bạn sẽ mệt mỏi rất nhiều khi chen lấn giữa dòng người đông đúc.</p>
<p>Crazy House có cảnh quan khá độc đáo vì thế hãy mang bộ đồ thích hợp cho phong cách ma quái. Ngoài ra, bạn nên tránh những buổi trưa nóng để leo lên những cầu thang ở đây.</p>
<p><figure id="attachment_1619" aria-describedby="caption-attachment-1619" style="width: 960px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1619" src="https://media.huynhhieutravel.com/Crazy-House6.jpg" alt="Những khách du lịch chụp hình ở Crazy House" width="960" height="720" srcset="https://media.huynhhieutravel.com/Crazy-House6.jpg 960w, https://media.huynhhieutravel.com/Crazy-House6-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1619" class="wp-caption-text">Những khách du lịch chụp hình ở Crazy House</figcaption></figure></p>
<h2>Giá vé Crazy House</h2>
<p><strong>Giá vé vào cổng</strong>: 50.000đ/người.</p>
<p><strong>Giá gửi xe</strong>: 5.000đ/xe.</p>
<h4>Giá phòng nghỉ ở Crazy House</h4>
